{"query": "import os, glob

candidates = []
for root in [".", "/mnt/data", "/content", "data", "/home", "/tmp"]:
    if os.path.exists(root):
        for path in glob.glob(os.path.join(root, "**", "*"), recursive=True):
            if os.path.isfile(path):
                ext = os.path.splitext(path)[1].lower()
                if ext in {".csv", ".tsv", ".json", ".jsonl", ".parquet", ".xlsx", ".xls",
                           ".feather", ".orc", ".txt", ".yaml", ".yml"}:
                    candidates.append(path)

print("Candidate files:", sorted(set(candidates)) or "NONE")

import pandas as pd
dfs = {k: v.shape for k, v in globals().items() if isinstance(v, pd.DataFrame)}
print("DataFrames in session:", dfs or "NONE")

print("CWD:", os.getcwd(), "->", sorted(os.listdir(".")))"}

